<?php
namespace App\Services\Commerce;use App\Models\{Order,OrderItem};use Illuminate\Support\Facades\DB;class InventoryService{public function reservedQuantities(array $ids,?int $exclude=null):array{if(!$ids)return[];return OrderItem::select('order_items.ticket_type_id',DB::raw('SUM(order_items.quantity) reserved_quantity'))->join('orders','orders.id','=','order_items.order_id')->whereIn('order_items.ticket_type_id',$ids)->when($exclude,fn($q)=>$q->where('orders.id','!=',$exclude))->where(fn($q)=>$q->where('orders.status',Order::STATUS_PAID)->orWhere(fn($q)=>$q->where('orders.status',Order::STATUS_PENDING_PAYMENT)->where('orders.expires_at','>',now())))->groupBy('order_items.ticket_type_id')->get()->mapWithKeys(fn($r)=>[(int)$r->ticket_type_id=>(int)$r->reserved_quantity])->all();}public function availableQuantity(int $capacity,int $reserved):int{return max(0,$capacity-$reserved);}}